using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Data;using MyExpenseTracker.Api.Models;namespace MyExpenseTracker.Api.Controllers;[Authorize,ApiController,Route("api/dashboard")]public class DashboardController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult>Get(){var a=await db.Accounts.ToListAsync();var t=await db.Transactions.ToListAsync();var months=Enumerable.Range(0,12).Select(i=>{var d=DateTime.Today.AddMonths(-11+i);var r=t.Where(x=>x.TransactionDate.Year==d.Year&&x.TransactionDate.Month==d.Month);return new{label=d.ToString("MMM yyyy"),income=r.Where(x=>x.Kind==TransactionKind.Income).Sum(x=>x.Amount),expense=r.Where(x=>x.Kind==TransactionKind.Expense).Sum(x=>x.Amount)};});var balances=a.Select(x=>new{x.Id,x.Name,x.Type,balance=x.OpeningBalance+t.Where(y=>y.AccountId==x.Id).Sum(y=>y.Kind==TransactionKind.Income?y.Amount:-y.Amount)});return Ok(new{months,accounts=balances});}}